// src/components/portfolio/Portfolio.js
import React, { useState, useEffect } from 'react';
import { useTheme } from '../../contexts/ThemeContext';
import { tradeAPI } from '../../services/api';

// Словарь для названий инструментов
const INSTRUMENT_NAMES = {
  'BBG004730N88': 'Сбербанк',
  'BBG004730RP0': 'Газпром',
  'BBG00475JZZ6': 'Лукойл',
  'BBG006L8G4H1': 'Яндекс',
  'BBG004S681W1': 'ВТБ',
  'BBG00475K2X9': 'Роснефть',
  'BBG004RVFCY3': 'Магнит',
  'BBG004S683W7': 'Татнефть',
  'BBG004S68B31': 'АЛРОСА',
  'RUB000UTSTOM': 'Наличные рубли'
};

// Словарь для секторов
const INSTRUMENT_SECTORS = {
  'BBG004730N88': 'Финансы',
  'BBG004730RP0': 'Энергетика',
  'BBG00475JZZ6': 'Энергетика',
  'BBG006L8G4H1': 'Технологии',
  'BBG004S681W1': 'Финансы',
  'BBG00475K2X9': 'Энергетика',
  'BBG004RVFCY3': 'Потребительские товары',
  'BBG004S683W7': 'Энергетика',
  'BBG004S68B31': 'Добыча',
  'RUB000UTSTOM': 'Деньги'
};

export default function Portfolio() {
  const [portfolioData, setPortfolioData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const { isDark } = useTheme();

  useEffect(() => {
    loadPortfolioData();
  }, []);

  const loadPortfolioData = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const response = await tradeAPI.getPortfolio();
      const apiData = response.data;
      
      // Преобразуем данные из API в нужный формат
      const processedData = processPortfolioData(apiData);
      setPortfolioData(processedData);
      
    } catch (err) {
      console.error('Ошибка загрузки портфеля:', err);
      setError('Не удалось загрузить данные портфеля. Проверьте подключение к серверу.');
      
      // Запасные данные для демонстрации
      setPortfolioData(getFallbackPortfolioData());
    } finally {
      setLoading(false);
    }
  };

  const processPortfolioData = (apiData) => {
    // Фильтруем только акции (исключаем валюту)
    const stockPositions = apiData.positions.filter(pos => pos.instrument_type === 'share');
    
    // Рассчитываем общую прибыль
    const totalProfit = stockPositions.reduce((sum, position) => {
      return sum + (position.expected_yield || 0);
    }, 0);
    
    // Рассчитываем общую стоимость акций
    const totalStocksValue = stockPositions.reduce((sum, position) => {
      return sum + (position.value || 0);
    }, 0);
    
    // Рассчитываем доходность в процентах
    const totalCostBasis = stockPositions.reduce((sum, position) => {
      const avgPrice = position.price || 0;
      const quantity = position.quantity || 0;
      return sum + (avgPrice * quantity);
    }, 0);
    
    const profitPercent = totalCostBasis > 0 ? (totalProfit / totalCostBasis) * 100 : 0;

    // Обрабатываем каждую позицию
    const processedPositions = stockPositions.map(position => {
      const quantity = position.quantity || 0;
      const currentPrice = position.price || 0;
      const marketValue = position.value || 0;
      const profit = position.expected_yield || 0;
      
      // Рассчитываем среднюю цену (если нет в API)
      const avgPrice = quantity > 0 ? (marketValue - profit) / quantity : 0;
      
      // Рассчитываем процент прибыли
      const costBasis = avgPrice * quantity;
      const profitPercent = costBasis > 0 ? (profit / costBasis) * 100 : 0;

      return {
        figi: position.figi,
        symbol: position.ticker,
        name: INSTRUMENT_NAMES[position.figi] || position.ticker,
        quantity: quantity,
        avgPrice: avgPrice,
        currentPrice: currentPrice,
        marketValue: marketValue,
        costBasis: costBasis,
        profit: profit,
        profitPercent: profitPercent,
        sector: INSTRUMENT_SECTORS[position.figi] || 'Другое',
        instrument_type: position.instrument_type,
        currency: position.currency
      };
    });

    return {
      totalValue: apiData.total_value || 0,
      cashBalance: apiData.cash_balance || 0,
      totalStocksValue: totalStocksValue,
      totalProfit: totalProfit,
      profitPercent: profitPercent,
      positionsCount: stockPositions.length,
      positions: processedPositions
    };
  };

  const getFallbackPortfolioData = () => ({
    totalValue: 70026.03,
    cashBalance: 68441.23,
    totalStocksValue: 1584.8,
    totalProfit: 0,
    profitPercent: 0,
    positionsCount: 1,
    positions: [
      { 
        figi: "BBG004S68B31",
        symbol: 'ALRS', 
        name: 'АЛРОСА', 
        quantity: 40, 
        avgPrice: 39.62, 
        currentPrice: 39.62, 
        marketValue: 1584.8, 
        costBasis: 1584.8, 
        profit: 0, 
        profitPercent: 0,
        sector: 'Добыча',
        instrument_type: 'share',
        currency: 'RUB'
      }
    ]
  });

  const formatCurrency = (value) => {
    return value.toLocaleString('ru-RU', { 
      minimumFractionDigits: 2, 
      maximumFractionDigits: 2 
    });
  };

  if (loading) {
    return (
      <div className="flex justify-center items-center h-64">
        <div className={`animate-spin rounded-full h-12 w-12 border-b-2 ${
          isDark ? 'border-cyan-500' : 'border-blue-500'
        }`}></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className={`rounded-3xl p-8 text-white shadow-2xl ${
        isDark
          ? 'bg-gradient-to-r from-green-600 to-cyan-600'
          : 'bg-gradient-to-r from-blue-500 to-purple-600'
      }`}>
        <div className="flex justify-between items-center">
          <div>
            <h1 className="text-3xl font-bold mb-2">Портфель</h1>
            <p className={isDark ? 'text-cyan-100' : 'text-blue-100'}>
              Детальный обзор ваших инвестиций
            </p>
          </div>
          <button
            onClick={loadPortfolioData}
            className={`px-4 py-2 rounded-2xl font-semibold text-white bg-white/20 hover:bg-white/30 transition-all duration-300 ${
              isDark ? 'hover:shadow-lg' : 'hover:shadow-md'
            }`}
          >
            Обновить
          </button>
        </div>
      </div>

      {error && (
        <div className={`rounded-2xl p-4 border ${
          isDark ? 'bg-red-500/10 border-red-500/30 text-red-300' : 'bg-red-50 border-red-200 text-red-700'
        }`}>
          <div className="flex items-center">
            <svg className="w-5 h-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            {error}
          </div>
        </div>
      )}

      {/* Сводка портфеля */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Общая стоимость</p>
          <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
            {formatCurrency(portfolioData.totalValue)} ₽
          </p>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            Включая наличные
          </p>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Общая прибыль</p>
          <p className={`text-2xl font-bold mt-1 ${
            portfolioData.totalProfit >= 0 
              ? 'text-green-600 dark:text-green-400'
              : 'text-red-600 dark:text-red-400'
          }`}>
            {portfolioData.totalProfit >= 0 ? '+' : ''}{formatCurrency(portfolioData.totalProfit)} ₽
          </p>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            По акциям
          </p>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Доходность</p>
          <p className={`text-2xl font-bold mt-1 ${
            portfolioData.profitPercent >= 0 
              ? 'text-green-600 dark:text-green-400'
              : 'text-red-600 dark:text-red-400'
          }`}>
            {portfolioData.profitPercent >= 0 ? '+' : ''}{portfolioData.profitPercent.toFixed(2)}%
          </p>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            По акциям
          </p>
        </div>

        <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
          <p className="text-sm font-medium text-gray-600 dark:text-gray-400">Акций в портфеле</p>
          <p className="text-2xl font-bold text-gray-900 dark:text-white mt-1">
            {portfolioData.positionsCount}
          </p>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
            Позиции
          </p>
        </div>
      </div>

      {/* Информация о наличных */}
      <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 p-6">
        <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-4">Наличные средства</h3>
        <div className="flex items-center justify-between">
          <div>
            <p className="text-2xl font-bold text-gray-900 dark:text-white">
              {formatCurrency(portfolioData.cashBalance)} ₽
            </p>
            <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
              Доступно для инвестиций
            </p>
          </div>
          <div className={`p-3 rounded-2xl ${
            isDark ? 'bg-blue-500/20' : 'bg-blue-100'
          }`}>
            <svg className="w-6 h-6 text-blue-600 dark:text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1" />
            </svg>
          </div>
        </div>
      </div>

      {/* Детали портфеля */}
      <div className="bg-white dark:bg-gray-800 rounded-3xl shadow-lg border border-gray-200 dark:border-gray-700 overflow-hidden">
        <div className="px-6 py-4 border-b border-gray-200 dark:border-gray-700 flex justify-between items-center">
          <h3 className="text-xl font-semibold text-gray-800 dark:text-white">Акции в портфеле</h3>
          <span className="text-sm text-gray-500 dark:text-gray-400">
            Обновлено: {new Date().toLocaleTimeString('ru-RU')}
          </span>
        </div>
        <div className="overflow-x-auto">
          {portfolioData.positions.length > 0 ? (
            <table className="w-full">
              <thead>
                <tr className={`border-b border-gray-200 dark:border-gray-700 ${
                  isDark ? 'bg-gray-700/50' : 'bg-gray-50'
                }`}>
                  <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Актив</th>
                  <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Количество</th>
                  <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Средняя цена</th>
                  <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Текущая цена</th>
                  <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Рыночная стоимость</th>
                  <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Прибыль</th>
                  <th className="text-left py-4 px-6 text-sm font-medium text-gray-600 dark:text-gray-400">Сектор</th>
                </tr>
              </thead>
              <tbody>
                {portfolioData.positions.map((position, index) => (
                  <tr 
                    key={index} 
                    className={`border-b border-gray-200 dark:border-gray-700 hover:${
                      isDark ? 'bg-gray-700/30' : 'bg-gray-50'
                    } transition-colors duration-200`}
                  >
                    <td className="py-4 px-6">
                      <div className="flex items-center space-x-3">
                        <div className={`w-10 h-10 rounded-2xl flex items-center justify-center ${
                          position.profit >= 0 
                            ? (isDark ? 'bg-green-500/20' : 'bg-green-100')
                            : (isDark ? 'bg-red-500/20' : 'bg-red-100')
                        }`}>
                          <span className={`font-bold text-sm ${
                            position.profit >= 0 
                              ? (isDark ? 'text-green-400' : 'text-green-600')
                              : (isDark ? 'text-red-400' : 'text-red-600')
                          }`}>
                            {position.symbol}
                          </span>
                        </div>
                        <div>
                          <p className="font-semibold text-gray-800 dark:text-white">{position.name}</p>
                          <p className="text-sm text-gray-600 dark:text-gray-400">{position.symbol}</p>
                        </div>
                      </div>
                    </td>
                    <td className="py-4 px-6 text-gray-800 dark:text-white">
                      {position.quantity.toLocaleString('ru-RU')} шт
                    </td>
                    <td className="py-4 px-6 text-gray-800 dark:text-white">
                      {formatCurrency(position.avgPrice)} ₽
                    </td>
                    <td className="py-4 px-6 text-gray-800 dark:text-white">
                      {formatCurrency(position.currentPrice)} ₽
                    </td>
                    <td className="py-4 px-6 text-gray-800 dark:text-white">
                      {formatCurrency(position.marketValue)} ₽
                    </td>
                    <td className="py-4 px-6">
                      <div className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium ${
                        position.profit >= 0
                          ? (isDark ? 'bg-green-500/20 text-green-400' : 'bg-green-100 text-green-700')
                          : (isDark ? 'bg-red-500/20 text-red-400' : 'bg-red-100 text-red-700')
                      }`}>
                        {position.profit >= 0 ? '+' : ''}{formatCurrency(position.profit)} ₽ ({position.profitPercent.toFixed(2)}%)
                      </div>
                    </td>
                    <td className="py-4 px-6">
                      <div className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium ${
                        isDark ? 'bg-blue-500/20 text-blue-400' : 'bg-blue-100 text-blue-700'
                      }`}>
                        {position.sector}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          ) : (
            <div className="text-center py-12">
              <div className={`w-16 h-16 rounded-2xl flex items-center justify-center mx-auto mb-4 ${
                isDark ? 'bg-gray-700' : 'bg-gray-100'
              }`}>
                <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
              <h3 className="text-lg font-semibold text-gray-800 dark:text-white mb-2">Нет акций в портфеле</h3>
              <p className="text-gray-600 dark:text-gray-400">
                Начните инвестировать, чтобы увидеть свои позиции здесь
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
